-- Report ID : RPT_013
-- Report    : Inventory Detail
-- Module    : Other
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                       AS report_date,     TRUNC(SYSDATE)                                       AS valuation_as_of_date,     ils.LOC                                              AS warehouse_id,     wh.WH_NAME                                           AS warehouse_name,     wh.PHYSICAL_WH                                       AS physical_wh_id,     wh.STOCKHOLDING_IND                                  AS stockholding_ind,     im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,     d.PROFIT_CALC_TYPE                                   AS accounting_method,     CASE d.PROFIT_CALC_TYPE         WHEN 1 THEN 'Cost Method'         WHEN 2 THEN 'Retail Method'     END                                                  AS accounting_method_desc,     im.CLASS                                             AS class_no,     c.CLASS_NAME                                         AS class_name,     im.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                          AS subclass_name,     im.ITEM                                              AS item_id,     im.ITEM_DESC                                         AS item_description,     im.ITEM_LEVEL                                        AS item_level,     im.TRAN_LEVEL                                        AS tran_level,     im.STANDARD_UOM                                      AS uom,     im.PACK_IND                                          AS pack_ind,     im.STATUS                                            AS item_status,     il.STATUS                                            AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS item_loc_status_desc,     ils.STOCK_ON_HAND                                    AS stock_on_hand,     ils.TSF_RESERVED_QTY                                 AS transfer_reserved_qty,     ils.RTV_QTY                                          AS rtv_qty,     ils.NON_SELLABLE_QTY                                 AS non_sellable_qty,     ils.CUSTOMER_RESV                                    AS customer_reserved_qty,     ils.CUSTOMER_BACKORDER                               AS customer_backorder_qty,      (ils.STOCK_ON_HAND         - NVL(ils.TSF_RESERVED_QTY, 0)         - NVL(ils.RTV_QTY, 0)         - NVL(ils.NON_SELLABLE_QTY, 0)         - NVL(ils.CUSTOMER_RESV, 0))                     AS available_qty,     so.STD_AV_IND                                        AS cost_method_flag,     CASE so.STD_AV_IND         WHEN 'A' THEN 'Average Cost'         WHEN 'S' THEN 'Standard Cost'     END                                                  AS cost_method_desc,     ils.AV_COST                                          AS weighted_avg_cost,     ils.UNIT_COST                                        AS current_unit_cost,     ROUND(ils.STOCK_ON_HAND * ils.AV_COST, 4)           AS total_inventory_value_at_cost,      ROUND(NVL(ils.NON_SELLABLE_QTY,0)   * ils.AV_COST, 4) AS non_sellable_value,     ROUND(NVL(ils.RTV_QTY,0)            * ils.AV_COST, 4) AS rtv_pending_value,     ROUND(NVL(ils.TSF_RESERVED_QTY,0)   * ils.AV_COST, 4) AS transfer_reserved_value,      ROUND(         (ils.STOCK_ON_HAND             - NVL(ils.TSF_RESERVED_QTY, 0)             - NVL(ils.RTV_QTY, 0)             - NVL(ils.NON_SELLABLE_QTY, 0)             - NVL(ils.CUSTOMER_RESV, 0))         * ils.AV_COST     , 4)                                                 AS available_inventory_value,     il.UNIT_RETAIL                                       AS unit_retail,     ROUND(ils.STOCK_ON_HAND * il.UNIT_RETAIL, 4)        AS total_inventory_value_at_retail,     ils.LAST_UPDATE_DATETIME                             AS last_update_datetime,     'RMS'                                                AS system_of_record  FROM     MFCS_RDS.RDS_WV_ITEM_LOC_SOH          ils      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC        il   ON  ils.ITEM         = il.ITEM                                               AND  ils.LOC          = il.LOC                                               AND  ils.LOC_TYPE     = il.LOC_TYPE      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  ils.ITEM         = im.ITEM                                               AND  im.TRAN_LEVEL    = im.ITEM_LEVEL      JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT          = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS           c    ON  im.DEPT          = c.DEPT                                               AND  im.CLASS         = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS        sc   ON  im.DEPT          = sc.DEPT                                               AND  im.CLASS         = sc.CLASS                                               AND  im.SUBCLASS      = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_WH              wh   ON  ils.LOC          = wh.WH      CROSS JOIN MFCS_RDS.RDS_WV_SYSTEM_OPTIONS so  WHERE     ils.LOC_TYPE         = 'W'     AND ils.STOCK_ON_HAND != 0     AND il.STATUS         IN ('A', 'C', 'I')  ORDER BY     wh.WH_NAME,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC